import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.backends.backend_pdf import PdfPages
import json,textwrap
from pathlib import Path
root=Path(__file__).resolve().parents[1]; out=root/'output/pdf'; data=root/'results/public-kernel-final'
rows=json.loads((data/'summary.json').read_text()); comps=json.loads((data/'comparisons.json').read_text())
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10})
navy='#16324F'; teal='#087F8C'
pdf=PdfPages(out/'three_seed_sparse_mpc_report.pdf')
def base(title,sub=''):
 f=plt.figure(figsize=(8.27,11.69));f.text(.09,.945,title,size=22,weight='bold',color=navy);f.text(.09,.91,sub,size=10,color='#52616B');return f
def prose(f,blocks,y=.85):
 for heading,body in blocks:
  f.text(.09,y,heading,size=13,weight='bold',color=teal); y-=.032
  for para in body.split('\n'):
   lines=textwrap.wrap(para,94)
   f.text(.09,y,'\n'.join(lines),size=10.3,va='top',linespacing=1.5)
   y-=len(lines)*.019+.023
  y-=.014
 return y
def save(f,n):
 f.text(.09,.045,'SPARSE PCA / THREE-SEED EXPERIMENT',size=8,color='#64748B');f.text(.9,.045,str(n),size=9)
 pdf.savefig(f);f.savefig(out/f'preview-{n}.png',dpi=100);plt.close(f)
f=base('Sparse PCA under MPC','Methodology and results | Seeds 17, 7 and 29 | 25 November 2026')
prose(f,[('Why study this problem?', 'Hospitals may want to learn shared gene-expression trends without disclosing their expression matrices. Single-cell RNA-sequencing matrices often contain many zeros. Avoiding arithmetic on these entries could reduce secure-computation cost, but sparse indexing, padding and fixed-point arithmetic introduce overhead. This study asks which implementation choices actually help.'),('What was tested?', 'A controlled synthetic experiment compared dense arithmetic with three public-support sparse kernels on 24 cells and 12 genes, partitioned across three hospitals. It isolates grouping and fixed-point truncation placement while retaining the same centered-PCA operator. It does not use patient data or establish rare-disease biological findings.'),('Main findings', 'Accumulating products before fixed-point truncation gives a repeatable matrix-kernel advantage at 75% or more zeros. Kernel speedups over dense range from about 1.18x to 2.56x across the successful fixtures. Grouping alone does not meet the predeclared 10% improvement criterion.\nNo tested variant meets that criterion for complete execution against dense. Setup, input, centering correction and output costs dilute the kernel savings. Communication benefits are substantial at the highest sparsities.'),('Evidence base', 'All 1,944 trial executions passed, comprising 1,620 measured trials and 324 warm-ups. All 112 validation jobs and all 12 separate PC1 confirmations passed under a documented revised accuracy policy. Confidence intervals remain paired within each seed and fixture; the three seeds are not pooled into a larger artificial sample.')]);save(f,1)
f=base('Preserving centered PCA','The optimization changes evaluation, while retaining the mathematical target')
prose(f,[('Implicit centering preserves sparse storage', 'Let X stack the hospital matrices by rows, C denote the total cell count, and mu be the global column mean. Subtracting the mean explicitly generally turns zero entries into nonzeros. Instead, retain X in its original sparse form and evaluate the centered operator as follows:')],.85)
f.text(.13,.68,r'$\mu=\frac{1}{C}X^T\mathbf{1},\qquad A(v)=X^T(Xv)-C\mu(\mu^Tv)$',size=17,color=navy)
prose(f,[('How the computation runs', 'Each hospital supplies its local column sums as secret inputs. Their secure sum gives the global mean. For each vector, the program first computes local X_i v products, then local X_i^T u_i products, and finally aggregates and applies the mean correction. It never constructs X^T X. The sample covariance is A/(C-1); that factor changes eigenvalues, not principal directions.'),('Security and leakage', 'Three-party semi-honest replicated sharing assumes at most one corrupted computing party. Expression values, means and intermediate vectors remain secret. Dimensions, support coordinates, padding, initialization and iteration budgets are public. The released checksums and validation outputs are explicit benchmark outputs. These findings do not extend to a hidden-support implementation.'),('Shared schedules and secret values', 'Public row-grouped and column-grouped schedules are prepared outside MPC. Both refer to the same secret value array, so the transpose requires no second upload of matrix values. Every matched variant receives the same public support metadata. Padding remains in the computation. The old coordinate-input-and-reveal program is retained as a separate loading-path diagnostic.')],.60);save(f,2)
f=base('A controlled comparison','Four implementations, identical objectives and arithmetic settings')
prose(f,[('The four kernels', 'Dense: optimized fixed-point dot products per destination.\nSparse scalar: individual fixed-point products and protected destination updates.\nSparse grouped: independent products, each truncated, followed by grouped accumulation.\nSparse dot: the same groups, accumulated with sfix.dot_product and reduced once per nonempty destination. Empty groups return a secret zero.'),('Why delayed truncation might help', 'The installed MP-SPDZ source confirms that a fixed-point dot product accumulates encoded integer products before reducing the scale. Fewer reductions can save protocol work. Grouping alone preserves the number of reductions and isolates scheduling and accumulation effects. Compiler audits confirm 89.6% fewer matrix scale reductions at full density for dot versus scalar. Compiler rounds are not treated as measured network rounds.'),('Fixed experimental controls', 'Shape: 24 x 12; hospital rows: 8 / 8 / 8. Uniform support without duplicate coordinates; nonzero values uniform on [0.4, 4.0]. Requested densities: 1%, 3%, 10%, 25%, 50%, 100%. Seeds: 17, then confirmations 7 and 29. Input scale: 0.25; fractional bits: 20; fixed-point width: 48; ring width: 128.\nFor m nonzeros, capacity per hospital is min(96, max(1,m)). The total padded capacities are 9, 27, 87, 216, 288 and 288 slots. Realized zero fractions are 98.96%, 96.88%, 89.93%, 75%, 50% and 0%.'),('Bounds and correctness gates', 'Before compilation, each untruncated group sum is bounded by d Amax Bmax for encoded operand bounds and group length d. Checks cover the signed ring, the installed k+f truncation width, protocol masking, means, correction, norms, Rayleigh products and checksum accumulation. Unsafe cases are rejected. Actual compilation provides additional primitive-specific checks.')]);save(f,3)
f=base('Measuring the right quantities','Correctness first; paired comparisons within each fixture')
prose(f,[('Validation and accuracy', 'Every kernel is checked against explicitly and implicitly centered floating-point references and quantized-input references. Tests include empty rows and columns, zero and constant matrices, aliasing padding, multiple contributions, signed vectors, cancellation and unequal hospital partitions. All 32 individual outputs are checked before performance collection.'),('A documented tolerance revision', 'The initial rule was L2 error <= 0.001 + 0.0001 times the reference norm. One adversarial cancellation vector produced 0.00100047 absolute error with a zero mathematical answer. A pre-execution deterministic model had already reached 0.001804. After investigation, the absolute floor was uniformly revised to 0.002; the relative term and arithmetic were unchanged. Original failures remain preserved.\nAll 4,608 primary validation comparisons and all 2,160 single-trial output comparisons also pass the original rule. Aggregate checksum checks pass the original budgets. A checksum cannot certify every individual output in every repeated trial.'),('Two operator workloads and separate PC1 confirmation', 'Single application includes process startup and input handling. The repeated workload loads the matrix once and applies the operator independently to 32 predetermined unit vectors, supplied identically as secret inputs before timing. Every result contributes to a checksum revealed after timing. This workload is not power iteration. A separate 20-iteration PC1 test uses the same initialization and accuracy targets across variants.'),('Repetitions, clocks and decision rule', 'Each fixture uses two warm-ups and ten measured rounds, with variant order randomized within rounds. Report medians, quartiles and paired 95% bootstrap intervals from 10,000 resamples of matching rounds. Convincing runtime evidence requires at least 10% lower median time (speedup >= 1/0.9) and an interval supporting speedup.\nThe original parent process used timeout polling, adding coarse exit-detection delays. That run was preserved and excluded from combined wall-time inference. Corrected runs use blocking waitpid observations. Internal MPC timers and communication counters were unaffected.')]);save(f,4)
f=base('Kernel gains replicate across seeds','32 independent applications | Dense time / sparse-dot time | Higher is better')
colors={17:'#087F8C',7:'#D97706',29:'#7950A3'}
for index,(metric,title) in enumerate([('kernel_seconds','Forward + transpose kernels'),('complete_seconds','Complete execution incl. schedule preparation')]):
 ax=f.add_axes([.13,.58-index*.30,.78,.23])
 for seed in [17,7,29]:
  ds=[]
  for c in comps:
   if c['workload']=='batch' and c['baseline']=='dense' and c['variant']=='sparse_dot' and c['metric']==metric and f'seed-{seed}-' in c['fixture']:
    row=next(r for r in rows if r['fixture']==c['fixture'] and r['variant']=='dense' and r['workload']=='batch');ds.append((row['density']*100,c))
  ds.sort(); xx=[d[0] for d in ds]; yy=[d[1]['speedup'] for d in ds]
  ax.errorbar(xx,yy,yerr=[[d[1]['speedup']-d[1]['ci95'][0] for d in ds],[d[1]['ci95'][1]-d[1]['speedup'] for d in ds]],marker='o',capsize=3,label=f'Seed {seed}',color=colors[seed],lw=1.2)
 ax.axhline(1,color='gray',lw=1);ax.axhline(1/.9,color='gray',ls=':',lw=1)
 ax.set_xscale('log');ax.set_xticks([1,3,10,25,50,100],labels=['1','3','10','25','50','100']);ax.set_xlabel('Nonzero density (%)');ax.set_ylabel('Speedup');ax.set_title(title,loc='left',size=11);ax.grid(alpha=.15);ax.legend(fontsize=8,ncol=3)
prose(f,[('Reading the figures', 'The solid reference is equal performance; the dotted line marks the median speedup needed for 10% less time. A convincing finding also requires a lower confidence bound above 1. Kernel benefit meets this rule at the four lowest densities for every seed. No complete-execution fixture meets the rule.\nAt 50% nonzero density, padding already fills the full matrix capacity. Extra observed sparsity then supplies little arithmetic advantage. The coarse grid brackets a kernel-benefit boundary between 50% and 75% zeros; it does not identify a precise crossover.')],.21);save(f,5)
f=base('What the results establish','Practical conclusions, scope and reproducibility')
prose(f,[('Which optimization helps?', 'Delayed truncation is the effective optimization. At density 3.125% and above, sparse dot convincingly beats scalar sparse kernels across all three seeds, reaching about 5.7x. At the lowest density, scalar is slightly faster for seed 7 and about 6% faster for seed 29. Grouping alone never meets the 10% improvement criterion for batch kernels or complete execution.'),('Communication and complete runtime', 'Sparse dot reduces total batch communication by about 64-65%, 50-54% and 24-30% at the three highest sparsities. At 75% zeros, savings range from 0.12% to 5.9%; at 50% and 0% zeros there is no saving. Grouping alone leaves communication totals unchanged.\nSome complete-time intervals support smaller runtime improvements. The best sparse-dot batch point estimate is 1.098x, a time reduction of 8.9%, below the predeclared 10% threshold. Kernel gains therefore provide evidence about the matrix steps; complete-application claims require their own measurement.'),('PC1 and limits of generalization', 'All 12 PC1 confirmations meet alignment >0.999, eigenvalue relative error <1%, and norm error <0.01. Worst alignment is 0.999341 and worst eigenvalue error is 0.0193%. Seed 29 has residual about 0.0051 after 20 iterations, reflecting slower convergence despite meeting the targets.\nThese are small, uniformly supported synthetic matrices on localhost with public support and fixed padding. The study establishes no advantage for larger matrices, private support, WAN deployment or real scRNA-seq preprocessing. The three seeds vary fixtures; they do not cover every support distribution.')]);save(f,6)
f=base("Sources and reproducibility","Repository artifacts and primary framework documentation")
prose(f,[('Reproducing and auditing the findings', 'Code and sources: mpc/public_kernel.mpc; src/sparse_pca/public_kernel.py; configs/public-kernel.json; PUBLIC_KERNEL_EXPERIMENT.md. Installed MP-SPDZ revision: f5f0cd2433c61d464666cbae19da16ac197d7a75.\nCombined tables: results/public-kernel-final/summary.csv and comparisons.csv. audit.json records sources, counts, PC1 checks and original-policy checks. Raw logs remain under public-kernel-clock-v2 and public-kernel-confirmation. Rebuild the combined analysis with: python -m sparse_pca.public_kernel combine --out results/public-kernel-final.\nAPI context: MP-SPDZ Compiler Optimizations (v0.4.1), mp-spdz.readthedocs.io/en/v0.4.1/optimization.html; High-Level Interface, mp-spdz.readthedocs.io/en/latest/Compiler.html. Installed-source excerpts and compiler proofs are retained with each experiment.')]);save(f,7)
pdf.close()
